const items = $input.all();
const posts = [];
for (const item of items) {
  const hits = item.json && item.json.hits ? item.json.hits : [];
  for (const hit of hits) {
    if (!hit.title) continue;
    posts.push({
      json: {
        title: hit.title || '',
        body: hit.story_text || hit.comment_text || '',
        url: 'https://news.ycombinator.com/item?id=' + hit.objectID,
        author: hit.author || '',
        subreddit: '',
        source: 'HackerNews',
        objectID: hit.objectID || '',
        points: hit.points || 0,
        num_comments: hit.num_comments || 0
      }
    });
  }
}
return posts;

const cx_query = `query { posts(order: NEWEST, topic: "customer-success", first: 20) { edges { node { id name tagline description url votesCount commentsCount createdAt } } } }`;
const competitor_query = `query { posts(order: NEWEST, first: 20) { edges { node { id name tagline description url votesCount createdAt comments(first: 5, order: VOTES) { edges { node { body } } } } } } }`;

return [
  { json: { query_type: 'cx_posts', graphql_query: cx_query } },
  { json: { query_type: 'competitor_search', graphql_query: competitor_query } }
];

const items = $input.all();
const posts = [];

for (const item of items) {
  const edges = item.json && item.json.data && item.json.data.posts ? item.json.data.posts.edges : [];

  for (const edge of edges) {
    const node = edge.node;
    if (!node || !node.name) continue;

    const commentBodies = (node.comments && node.comments.edges ? node.comments.edges : [])
      .map(e => e.node && e.node.body ? e.node.body : '')
      .filter(Boolean)
      .join(' | ');

    posts.push({
      json: {
        title: node.name || '',
        body: [node.tagline, node.description, commentBodies].filter(Boolean).join(' '),
        url: node.url || '',
        author: '',
        subreddit: '',
        source: 'ProductHunt',
        ph_id: node.id || '',
        votes: node.votesCount || 0,
        comments_count: node.commentsCount || 0
      }
    });
  }
}

return posts;

const keywords = ['nps','csat','ces','net promoter','customer feedback','customer satisfaction','feedback tool','survey tool','churn','customer effort','typeform','delighted','survicate','medallia','customer success','onboarding survey','qualtrics','hotjar','intercom survey','feedback loop'];
const items = $input.all();
return items.filter(item => {
  const text = (item.json.title + ' ' + item.json.body).toLowerCase();
  return keywords.some(kw => text.includes(kw));
});

const staticData = $getWorkflowStaticData('global');
if (!staticData.seenUrls) staticData.seenUrls = {};
const ONE_DAY = 24 * 60 * 60 * 1000;
const now = Date.now();
for (const url in staticData.seenUrls) {
  if (now - staticData.seenUrls[url] > ONE_DAY) delete staticData.seenUrls[url];
}
const items = $input.all();
const fresh = [];
for (const item of items) {
  const url = item.json.url;
  if (!url) continue;
  if (!staticData.seenUrls[url]) {
    staticData.seenUrls[url] = now;
    fresh.push(item);
  }
}
return fresh;

