const llmItems = $input.all();
const sourceItems = $('Dedup Static Memory').all();
const results = [];

for (let i = 0; i < llmItems.length; i++) {
  const item = llmItems[i];
  const source = sourceItems[i] ? sourceItems[i].json : {};
  const rawText = item.json.text || item.json.output || item.json.response || item.json.content || '';
  let parsed = {};

  try {
    const cleaned = String(rawText).replace(/```json\s*/gi, '').replace(/```\s*/g, '').trim();
    parsed = JSON.parse(cleaned);
  } catch (_) {
    parsed = {
      pain_point: 'Parse error',
      intent: 'learning',
      urgency: 'low',
      tool_mentioned: null,
      elvan_angle: '',
      score: 1,
      draft_reply: ''
    };
  }

  results.push({
    json: {
      ...source,
      pain_point: parsed.pain_point || '',
      intent: parsed.intent || 'learning',
      urgency: parsed.urgency || 'low',
      tool_mentioned: parsed.tool_mentioned || null,
      elvan_angle: parsed.elvan_angle || '',
      base_score: Number(parsed.score) || 1,
      draft_reply: parsed.draft_reply || '',
      llm_raw_output: String(rawText || '')
    }
  });
}

return results;

const intentKws = ['alternative','replace','replacement','looking for','recommend','switch','switching','what do you use','anyone using','anyone tried','moved away','moved from','migrated','shut down','shutdown'];
const competitorKws = ['delighted','survicate','typeform','qualtrics','medallia','hotjar','intercom'];
const items = $input.all();
const validItems = items.filter(item => {
  const url = String(item.json.url || '').trim();
  return /^https?:\/\//i.test(url);
});

if (items.length > 0 && validItems.length === 0) {
  throw new Error('Scoring received items, but all were missing valid URLs after Parse LLM Response.');
}

return validItems.map(item => {
  const title = item.json.title || '';
  const body = item.json.body || '';
  const source = item.json.source || '';
  const base_score = Number(item.json.base_score) || 1;
  const text = (title + ' ' + body).toLowerCase();
  let boost = 0;
  if (text.includes('?') && intentKws.some(kw => text.includes(kw))) boost += 3;
  if (competitorKws.some(kw => text.includes(kw))) boost += 2;
  if (source === 'HackerNews') {
    if ((Number(item.json.points) || 0) >= 10) boost += 1;
    if ((Number(item.json.num_comments) || 0) >= 3) boost += 1;
  }
  if (source === 'ProductHunt') {
    if ((Number(item.json.votes) || 0) >= 20) boost += 1;
    if ((Number(item.json.comments_count) || 0) >= 2) boost += 1;
  }
  const boosted_score = Math.min(10, base_score + boost);
  const tier = boosted_score >= 7 ? 'hot' : boosted_score >= 5 ? 'medium' : 'low';
  return {json: {...item.json, boosted_score, tier}};
});

const post = $json;
const normalizedSource = (() => {
  if (post.source === 'HackerNews') return 'hn';
  if (post.source === 'ProductHunt') return 'ph';
  return String(post.source || 'unknown').trim().toLowerCase() || 'unknown';
})();
const canonicalUrl = String(post.url || '').trim();
const externalId = String(post.objectID || post.ph_id || canonicalUrl || '').trim();
const dedupeId = canonicalUrl || externalId;
if (!dedupeId) {
  throw new Error('Prep Neon Signal Row requires a URL, objectID, or ph_id');
}
const priority = String(post.tier || 'low').trim().toLowerCase() || 'low';
return {
  json: {
    dedupe_key: `n8n:${normalizedSource}:${dedupeId}`,
    source: normalizedSource,
    source_system: 'n8n',
    workflow: 'workflow1-hn-producthunt',
    external_id: externalId || null,
    title: String(post.title || 'Untitled signal').trim(),
    body: String(post.body || '').trim() || null,
    url: canonicalUrl || null,
    author: String(post.author || '').trim() || null,
    subreddit: String(post.subreddit || '').trim() || null,
    intent: String(post.intent || 'learning').trim() || 'learning',
    urgency: String(post.urgency || 'low').trim() || 'low',
    priority,
    tool_mentioned: String(post.tool_mentioned || '').trim() || null,
    pain_point: String(post.pain_point || '').trim() || null,
    elvan_angle: String(post.elvan_angle || '').trim() || null,
    draft_reply: String(post.draft_reply || '').trim() || null,
    score: Number(post.boosted_score ?? post.base_score ?? 0),
    base_score: Number(post.base_score ?? 0),
    boosted_score: Number(post.boosted_score ?? post.base_score ?? 0),
    comments_count: Number(post.num_comments ?? post.comments_count ?? 0),
    upvotes: Number(post.points ?? post.votes ?? 0),
    alerted: false,
    hot_lead: priority === 'hot',
    occurred_at: new Date().toISOString()
  }
};

const checks = $input.all();
const preparedRows = $('Prep Neon Signal Row').all();
const fresh = [];
for (let i = 0; i < checks.length; i++) {
  const value = checks[i].json.exists;
  const exists = value === true || value === 'true' || value === 1 || value === '1';
  if (!exists && preparedRows[i]) fresh.push(preparedRows[i]);
}
return fresh;
